def routing_kernel(request):
    "Accept the public request and return a dict with stations and delivered as lists of IDs, outgoing as a mapping from every station ID to a list of (target_ID, exact Fraction probability, integer travel_time) rows, and can_deliver as the set of station IDs that can reach a delivered station, including delivered stations. Normalize each origin's weights. Preserve parallel routes with potentially different times, and retain terminal and no-delivery states.\n\nLocal check: Pass S with routes to delivered T of weights 1 and 3 and durations 2 and 6, plus a route to D of weight 2 and duration 9. Let D have only a self-loop. Assert that the three distinct S rows have probabilities 1/6, 1/2, and 1/3, and that can_deliver is exactly {'S', 'T'}."
    raise NotImplementedError

def station_outcomes(kernel):
    "Accept the normalized kernel with stations, delivered, outgoing, and can_deliver. Return the mapping from station ID to its public success and mean_if_success fields. Use exact rational values represented by integer numerator/denominator pairs. Preserve the unbounded time horizon, conditional mean, and the None mean when success probability is zero.\n\nLocal check: Feed a kernel where S repeats itself with probability 1/2 and time 2, reaches delivered T with probability 1/4 and time 5, and reaches dead D with probability 1/4 and time 11. Set can_deliver to {'S', 'T'}. Assert S has success 1/2 and conditional mean 7, T has success 1 and mean 0, and D has success 0 and mean None."
    raise NotImplementedError

from fractions import Fraction
import json

def fractions(x):
    if x is None:return None
    if not isinstance(x,list) or len(x)!=2 or any(type(v) is not int for v in x) or x[1]<=0:raise ValueError
    return Fraction(*x)

def normalize(ident,value,field=""):
    if ident in {"F18","F20"} and isinstance(value,list):
        q=fractions(value)
        return [q.numerator,q.denominator]
    if isinstance(value,dict):return {k:normalize(ident,v,k) for k,v in value.items()}
    return value

def check_value(ident,name,actual,wanted,context=None):
    try:
        if ident!="F17":
            return json.dumps(normalize(ident,actual),sort_keys=True)==json.dumps(normalize(ident,wanted),sort_keys=True)
        d=context.get("request",context);base=bytes.fromhex(d["base"]);out=bytearray();cost=head=0
        if set(actual)!={"cost","ops"} or type(actual["cost"]) is not int or not isinstance(actual["ops"],list):return False
        for op in actual["ops"]:
            if set(op)=={"literal"}:
                literal=bytes.fromhex(op["literal"])
                if not literal:return False
                out.extend(literal);cost+=d["literal_header"]+len(literal)*d["literal_unit"]
            elif set(op)=={"copy"}:
                offset,size=op["copy"]
                if type(offset) is not int or type(size) is not int or offset<0 or size<d["min_copy"] or offset+size>len(base):return False
                out.extend(base[offset:offset+size]);cost+=d["copy_header"]+abs(offset-head)*d["seek_unit"];head=offset+size
