from fractions import Fraction


def _solve_linear(rows, values):
    """Solve a square, non-singular system of exact rational equations."""
    size = len(rows)
    if size == 0:
        return []
    matrix = [rows[i][:] + [values[i]] for i in range(size)]

    for column in range(size):
        pivot = None
        for row in range(column, size):
            if matrix[row][column] != 0:
                pivot = row
                break
        if pivot is None:
            raise ValueError("singular routing system")
        if pivot != column:
            matrix[column], matrix[pivot] = matrix[pivot], matrix[column]

        pivot_value = matrix[column][column]
        for row in range(size):
            if row == column:
                continue
            factor = matrix[row][column] / pivot_value
            if factor == 0:
                continue
            for col in range(column, size + 1):
                matrix[row][col] -= factor * matrix[column][col]

    return [matrix[i][size] / matrix[i][i] for i in range(size)]


def _fraction_pair(value):
    return [value.numerator, value.denominator]


def station_outcomes(kernel):
    """Return success probability and conditional mean time for every station."""
    stations = kernel["stations"]
    delivered = kernel["delivered"]
    outgoing = kernel["outgoing"]
    can_deliver = kernel["can_deliver"]
    delivered_set = set(delivered)

    variables = [station for station in stations
                 if station in can_deliver and station not in delivered_set]
    index = {station: position for position, station in enumerate(variables)}
    size = len(variables)

    # Probability of eventual successful delivery.
    success_rows = []
    success_values = []
    for station in variables:
        row = [Fraction(0) for _ in range(size)]
        row[index[station]] = Fraction(1)
        value = Fraction(0)
        for target, probability, _travel_time in outgoing[station]:
            if target in delivered_set:
                value += probability
            elif target in index:
                row[index[target]] -= probability
            # Stations outside can_deliver never reach delivery, so their
            # success probability contributes zero.
        success_rows.append(row)
        success_values.append(value)

    success_vector = _solve_linear(success_rows, success_values)

    # Expected transit time weighted by the eventual-success indicator.
    time_rows = []
    time_values = []
    for station in variables:
        row = [Fraction(0) for _ in range(size)]
        row[index[station]] = Fraction(1)
        value = Fraction(0)
        for target, probability, travel_time in outgoing[station]:
            if target in delivered_set:
                value += probability * travel_time
            elif target in index:
                target_success = success_vector[index[target]]
                row[index[target]] -= probability
                value += probability * travel_time * target_success
            # Unsuccessful paths contribute zero expected success time.
        time_rows.append(row)
        time_values.append(value)

    time_vector = _solve_linear(time_rows, time_values)

    outcomes = {}
    for station in stations:
        if station in delivered_set:
            outcomes[station] = {
                "success": [1, 1],
                "mean_if_success": [0, 1],
            }
        elif station in index:
            position = index[station]
            success = success_vector[position]
            mean_if_success = None
            if success != 0:
                mean_if_success = time_vector[position] / success
                mean_if_success = _fraction_pair(mean_if_success)
            outcomes[station] = {
                "success": _fraction_pair(success),
                "mean_if_success": mean_if_success,
            }
        else:
            outcomes[station] = {
                "success": [0, 1],
                "mean_if_success": None,
            }

    return outcomes

