    def test_loop_and_dead_branch_conditional_mean(self):
        # S can loop, reach delivered T, or fall into dead D. Exercises the
        # unbounded horizon, a success probability below one, and the
        # conditional (not unconditional) mean.
        request = {
            "stations": ["S", "T", "D"],
            "delivered": ["T"],
            "routes": [
                {"from": "S", "to": "S", "weight": 2, "time": 2},
